        }
}

pub fn parseOptionDefinitions(globalThis: *JSGlobalObject, options_obj: JSValue, option_definitions: *std.array_list.Managed(OptionDefinition)) bun.JSError!void {
        _ = try validators.validateObject(globalThis, options_obj, "options", .{}, .{});
        var iter = try jsc.JSPropertyIterator(.{ .skip_empty_name = false, .include_value = true }).init(globalThis, ((options_obj.getObject()) orelse (unreachable)));
        _ = &iter;
        defer {
        _ = iter.deinit();
        }
        while (try iter.next()) |long_option| {
            var option = OptionDefinition{ .long_name = String.init(long_option) };
            _ = &option;
            const obj: JSValue = (if (@typeInfo(@TypeOf(iter)) == .@"enum") @intFromEnum(iter) else iter.value);
            _ = try validators.validateObject(globalThis, obj, "options.{f}", .{ option.long_name }, .{});
            const option_type: JSValue = ((try obj.getOwn(globalThis, "type")) orelse (.js_undefined));
            option.type = try validators.validateStringEnum(OptionValueType, globalThis, option_type, "options.{f}.type", .{ option.long_name });
            if (try obj.getOwn(globalThis, "short")) |short_option| {
                _ = &short_option;
                _ = try validators.validateString(globalThis, short_option, "options.{f}.short", .{ option.long_name });
                var short_option_str = try short_option.toBunString(globalThis);
                _ = &short_option_str;
                if ((short_option_str.length() != 1)) {
                    const err = globalThis.toTypeError(.INVALID_ARG_VALUE, "options.{f}.short must be a single character", .{ option.long_name });
                    return globalThis.throwValue(err);
                }
                option.short_name = short_option_str;
            }
            if (try obj.getOwn(globalThis, "multiple")) |multiple_value| {
                _ = &multiple_value;
                if ((!multiple_value.isUndefined())) {
                    option.multiple = try validators.validateBoolean(globalThis, multiple_value, "options.{f}.multiple", .{ option.long_name });
                }
            }
            if (try obj.getOwn(globalThis, "default")) |default_value| {
                _ = &default_value;
                if ((!default_value.isUndefined())) {
                    switch (option.type) {
OptionValueType.string => {
if (option.multiple) {
                        _ = try validators.validateStringArray(globalThis, default_value, "options.{f}.default", .{ option.long_name });
                    } else {
                        _ = try validators.validateString(globalThis, default_value, "options.{f}.default", .{ option.long_name });
                    }
},
OptionValueType.boolean => {
if (option.multiple) {
                        _ = try validators.validateBooleanArray(globalThis, default_value, "options.{f}.default", .{ option.long_name });
                    } else {
                        _ = try validators.validateBoolean(globalThis, default_value, "options.{f}.default", .{ option.long_name });
                    }
},
}
                    option.default_value = default_value;
                }
            }
            var dv_tag: ?[]const u8 = null;
            _ = &dv_tag;
            if (option.default_value) |dv| {
                _ = &dv;
                dv_tag = bun.tagName(JSValue, dv);
            }
            _ = log("[OptionDef] \"{f}\" (type={s}, short={f}, multiple={d}, default={?s})", .{ String.init(long_option), @tagName(option.type), (if ((!option.short_name.isEmpty())) option.short_name else String.static("none")), @intFromBool(option.multiple), dv_tag });
            _ = try option_definitions.append(option);
        }
}

pub fn tokenizeArgs(ctx: *ParseArgsState, globalThis: *JSGlobalObject, args: ArgsSlice, options: []const OptionDefinition) bun.JSError!void {
        const num_args: u32 = (args.end - args.start);
        var index: u32 = 0;
        _ = &index;
        while ((index < num_args)) : (index = (index + 1)) {
            const arg_ref = ValueRef{ .jsvalue = try args.get(globalThis, index) };
            const arg = arg_ref.asBunString(globalThis);
            const token_rawtype = classifyToken(arg, options);
            _ = log(" [Arg #{d}] {s} ({f})", .{ index, @tagName(token_rawtype), arg });
            switch (token_rawtype) {
.option_terminator => {
_ = try ctx.handleToken(Token{ .@"option-terminator" = OptionTerminatorToken{ .index = index } });
            index = (index + 1);
            while ((index < num_args)) : (index = (index + 1)) {
                _ = try ctx.handleToken(Token{ .positional = PositionalToken{ .index = index, .value = ValueRef{ .jsvalue = try args.get(globalThis, index) } } });
            }
            break;
},
.lone_short_option => {
const short_option = arg.substringWithLen(1, 2);
            const option_idx = findOptionByShortName(short_option, options);
            var option_type = OptionValueType.boolean;
            _ = &option_type;
            if (option_idx) |idx| {
                _ = &idx;
                option_type = options[@as(usize, @intCast(idx))].type;
            }
            var value = ValueRef{ .jsvalue = .js_undefined };
            _ = &value;
            var has_inline_value = true;
            _ = &has_inline_value;
            if (((option_type == OptionValueType.string) and ((index + 1) < num_args))) {
                value = ValueRef{ .jsvalue = try args.get(globalThis, (index + 1)) };
                has_inline_value = false;
                _ = log("   (lone_short_option consuming next token as value)", .{});
            }
            var opt_name = arg.substringWithLen(1, 2);
            _ = &opt_name;
            if (option_idx) |idx| {
                _ = &idx;
                opt_name = options[@as(usize, @intCast(idx))].long_name;
            }
            _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = index, .value = value, .inline_value = has_inline_value, .name = ValueRef{ .bunstr = opt_name }, .parse_type = OptionTokenParseType.lone_short_option, .raw = arg_ref, .option_idx = option_idx } });
            if ((!has_inline_value)) {
                index = (index + 1);
            }
},
.short_option_group => {
const original_arg_idx = index;
            const arg_len = arg.length();
            {
                var idx_in_optgroup: i32 = 1;
                _ = &idx_in_optgroup;
                const __end_1 = arg_len;
                while (idx_in_optgroup < __end_1) : (idx_in_optgroup += 1) {
                    const short_option = arg.substringWithLen(idx_in_optgroup, (idx_in_optgroup + 1));
                    const option_idx = findOptionByShortName(short_option, options);
                    var option_type = OptionValueType.boolean;
                    _ = &option_type;
                    if (option_idx) |idx| {
                        _ = &idx;
                        option_type = options[@as(usize, @intCast(idx))].type;
                    }
                    if (((option_type != OptionValueType.string) or (idx_in_optgroup == (arg_len - 1)))) {
                        var value = ValueRef{ .jsvalue = .js_undefined };
                        _ = &value;
                        var has_inline_value = true;
                        _ = &has_inline_value;
                        if (((option_type == OptionValueType.string) and ((index + 1) < num_args))) {
                            value = ValueRef{ .jsvalue = try args.get(globalThis, (index + 1)) };
                            has_inline_value = false;
                            _ = log("   (short_option_group short option consuming next token as value)", .{});
                        }
                        var opt_name = short_option;
                        _ = &opt_name;
                        if (option_idx) |i| {
                            _ = &i;
                            opt_name = options[@as(usize, @intCast(i))].long_name;
                        }
                        _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = original_arg_idx, .optgroup_idx = @intCast(idx_in_optgroup), .value = value, .inline_value = has_inline_value, .name = ValueRef{ .bunstr = opt_name }, .parse_type = OptionTokenParseType.lone_short_option, .raw = arg_ref, .option_idx = option_idx } });
                        if ((!has_inline_value)) {
                            index = (index + 1);
                        }
                    } else {
                        var opt_name = short_option;
                        _ = &opt_name;
                        if (option_idx) |i| {
                            _ = &i;
                            opt_name = options[@as(usize, @intCast(i))].long_name;
                        }
                        _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = original_arg_idx, .optgroup_idx = @intCast(idx_in_optgroup), .value = ValueRef{ .bunstr = cp_iter_slice(arg)[@intCast((idx_in_optgroup + 1))..] }, .inline_value = true, .name = ValueRef{ .bunstr = opt_name }, .parse_type = OptionTokenParseType.short_option_and_value, .raw = arg_ref, .option_idx = option_idx } });
                        break;
                    }
                }
            }
},
.short_option_and_value => {
const short_option = arg.substringWithLen(1, 2);
            const option_idx = findOptionByShortName(short_option, options);
            const value = cp_iter_slice(arg)[@intCast(2)..];
            var opt_name = arg.substringWithLen(1, 2);
            _ = &opt_name;
            if (option_idx) |idx| {
                _ = &idx;
                opt_name = options[@as(usize, @intCast(idx))].long_name;
            }
            _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = index, .value = ValueRef{ .bunstr = value }, .inline_value = true, .name = ValueRef{ .bunstr = opt_name }, .parse_type = OptionTokenParseType.short_option_and_value, .raw = ValueRef{ .bunstr = arg.substringWithLen(0, 2) }, .option_idx = option_idx } });
},
.lone_long_option => {
var long_option = cp_iter_slice(arg)[@intCast(2)..];
            _ = &long_option;
            var negative = false;
            _ = &negative;
            if ((ctx.allow_negative and long_option.hasPrefixComptime("no-"))) {
                long_option = cp_iter_slice(long_option)[@intCast(3)..];
                negative = true;
            }
            const option_idx = findOptionByLongName(long_option, options);
            var option_type = OptionValueType.boolean;
            _ = &option_type;
            if (option_idx) |idx| {
                _ = &idx;
                option_type = options[@as(usize, @intCast(idx))].type;
            }
            var value: ?JSValue = null;
            _ = &value;
            if ((((option_type == OptionValueType.string) and ((index + 1) < num_args)) and (!negative))) {
                value = try args.get(globalThis, (index + 1));
                _ = log("  (consuming next as value)", .{});
            }
            _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = index, .value = ValueRef{ .jsvalue = ((value) orelse (.js_undefined)) }, .inline_value = (value == null), .name = ValueRef{ .bunstr = long_option }, .parse_type = OptionTokenParseType.lone_long_option, .raw = arg_ref, .option_idx = option_idx, .negative = negative } });
            if ((value != null)) {
                index = (index + 1);
            }
},
.long_option_and_value => {
const equal_index = arg.indexOfAsciiChar(61);
            const eq_idx = ((equal_index) orelse (unreachable));
            const long_option = arg.substringWithLen(2, eq_idx);
            const value = cp_iter_slice(arg)[@intCast((eq_idx + 1))..];
            _ = try ctx.handleToken(Token{ .option = OptionToken{ .index = index, .value = ValueRef{ .bunstr = value }, .inline_value = true, .name = ValueRef{ .bunstr = long_option }, .parse_type = OptionTokenParseType.long_option_and_value, .raw = arg_ref, .option_idx = findOptionByLongName(long_option, options) } });
},
.positional => {
_ = try ctx.handleToken(Token{ .positional = PositionalToken{ .index = index, .value = arg_ref } });
},
}
        }
}

pub fn parseArgs(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!JSValue {
        _ = jsc.markBinding(@src());
        const config_value = callframe.argumentsAsArray(1)[0];
        var config: ?JSValue = null;
        _ = &config;
        if ((!config_value.isUndefined())) {
            config = config_value;
        }
        var config_args: JSValue = .js_undefined;
        _ = &config_args;
        if (config) |c| {
            _ = &c;
            config_args = ((try c.getOwn(globalThis, "args")) orelse (.js_undefined));
        }
        var args: ArgsSlice = undefined;
        _ = &args;
        if ((!config_args.isUndefinedOrNull())) {
            _ = try validators.validateArray(globalThis, config_args, "args", .{}, null);
            args = ArgsSlice{ .array = config_args, .start = 0, .end = @intCast(try config_args.getLength(globalThis)) };
        } else {
            args = try getDefaultArgs(globalThis);
        }
        var config_strict: JSValue = .true;
        _ = &config_strict;
        if (config) |c| {
            _ = &c;
            if (try c.getOwn(globalThis, "strict")) |strict_val| {
                _ = &strict_val;
                config_strict = strict_val;
            }
        }
        var config_allow_positionals: JSValue = JSValue.jsBoolean((!config_strict.toBoolean()));
        _ = &config_allow_positionals;
        if (config) |c| {
            _ = &c;
            if (try c.getOwn(globalThis, "allowPositionals")) |ap_val| {
                _ = &ap_val;
                config_allow_positionals = ap_val;
            }
        }
        var config_return_tokens: JSValue = .false;
        _ = &config_return_tokens;
        if (config) |c| {
            _ = &c;
            if (try c.getOwn(globalThis, "tokens")) |tokens_val| {
                _ = &tokens_val;
                config_return_tokens = tokens_val;
            }
        }
        var config_allow_negative: JSValue = .false;
        _ = &config_allow_negative;
        if (config) |c| {
            _ = &c;
            if (try c.getOwn(globalThis, "allowNegative")) |neg_val| {
                _ = &neg_val;
                config_allow_negative = neg_val;
            }
        }
        var config_options: JSValue = .js_undefined;
        _ = &config_options;
        if (config) |c| {
            _ = &c;
            if (try c.getOwn(globalThis, "options")) |opts_val| {
                _ = &opts_val;
                config_options = opts_val;
            }
        }
        const strict = try validators.validateBoolean(globalThis, config_strict, "strict", .{});
        if (config_allow_positionals.isUndefinedOrNull()) {
            config_allow_positionals = JSValue.jsBoolean((!strict));
        }
        const allow_positionals = try validators.validateBoolean(globalThis, config_allow_positionals, "allowPositionals", .{});
        const return_tokens = try validators.validateBoolean(globalThis, config_return_tokens, "tokens", .{});
        const allow_negative = try validators.validateBoolean(globalThis, config_allow_negative, "allowNegative", .{});
        var options_defs_allocator = std.heap.stackFallback(2048, globalThis.allocator());
        _ = &options_defs_allocator;
        var option_defs = std.array_list.Managed(OptionDefinition).init(options_defs_allocator.get());
        _ = &option_defs;
        defer {
        _ = option_defs.deinit();
        }
        if ((!config_options.isUndefinedOrNull())) {
            _ = try parseOptionDefinitions(globalThis, config_options, option_defs);
        }
        _ = log("Phase 1+2: tokenize args (args.len={d})", .{ (args.end - args.start) });
        const values = JSValue.createEmptyObjectWithNullPrototype(globalThis);
        const positionals = try jsc.JSValue.createEmptyArray(globalThis, 0);
        var tokens: JSValue = .js_undefined;
        _ = &tokens;
        if (return_tokens) {
            tokens = try jsc.JSValue.createEmptyArray(globalThis, 0);
        }
        var state = ParseArgsState{ .globalThis = globalThis, .option_defs = option_defs.items, .allow_positionals = allow_positionals, .strict = strict, .allow_negative = allow_negative, .values = values, .positionals = positionals, .tokens = tokens };
        _ = &state;
        _ = try tokenizeArgs((&state), globalThis, args, option_defs.items);
        _ = log("Phase 3: fill defaults", .{});
        for (option_defs.items) |option| {
            _ = &option;
            if (option.default_value) |default_value| {
                _ = &default_value;
                if ((!option.long_name.eqlComptime("__proto__"))) {
                    if ((try state.values.getOwn(globalThis, option.long_name) == null)) {
                        _ = log("  Setting \"{f}\" to default value", .{ option.long_name });
                        _ = try state.values.putMayBeIndex(globalThis, (&option.long_name), default_value);
                    }
                }
            }
        }
        _ = log("Phase 4: Build result object", .{});
        var result = JSValue.createEmptyObject(globalThis, (if (return_tokens) 3 else 2));
        _ = &result;
        if (return_tokens) {
            _ = result.put(globalThis, ZigString.static("tokens"), state.tokens);
        }
        _ = result.put(globalThis, ZigString.static("values"), state.values);
        _ = result.put(globalThis, ZigString.static("positionals"), state.positionals);
        return result;
}
